/**
 * Cross-validation against statsmodels 0.15 (fixture generated by scripts/gen_reference.py).
 * Three synthetic series of length 215 (same length as the monthly GVZ sample):
 * a random walk, a stationary AR(1), and a trend-stationary series.
 */
import { describe, expect, it } from "vitest";
import ref from "../fixtures/statsmodels_reference.json" with { type: "json" };
import { adfTest } from "../../src/stats/adf.js";
import { kpssTest } from "../../src/stats/kpss.js";
import { acf, ljungBox, pacf } from "../../src/stats/autocorrelation.js";

type Case = (typeof ref)["rw"];
const cases = Object.entries(ref) as [string, Case][];

describe.each(cases)("statsmodels parity: %s", (_name, c) => {
  for (const reg of ["c", "ct"] as const) {
    it(`ADF (${reg}, AIC autolag)`, () => {
      const expected = c[`adf_${reg}`];
      const r = adfTest(c.x, { regression: reg });
      expect(r.usedLag).toBe(expected.lag);
      expect(r.nobs).toBe(expected.nobs);
      expect(r.statistic).toBeCloseTo(expected.stat, 8);
      expect(r.pValue).toBeCloseTo(expected.p, 6);
      expect(r.criticalValues["5%"]).toBeCloseTo(expected.crit["5%"], 6);
    });

    it(`ADF (${reg}, fixed 3 lags)`, () => {
      const expected = c[`adf_${reg}_fixed3`];
      const r = adfTest(c.x, { regression: reg, lags: 3 });
      expect(r.statistic).toBeCloseTo(expected.stat, 8);
      expect(r.pValue).toBeCloseTo(expected.p, 6);
    });

    it(`KPSS (${reg}, 4 lags)`, () => {
      const expected = c[`kpss_${reg}`];
      const r = kpssTest(c.x, { regression: reg, lags: 4 });
      expect(r.statistic).toBeCloseTo(expected.stat, 8);
      expect(r.pValue).toBeCloseTo(expected.p, 8);
    });
  }

  it("ACF / PACF", () => {
    const a = acf(c.x, 24);
    const p = pacf(c.x, 24);
    a.forEach((v, i) => expect(v).toBeCloseTo(c.acf[i]!, 10));
    p.forEach((v, i) => expect(v).toBeCloseTo(c.pacf[i + 1]!, 8));
  });

  it("Ljung-Box with model_df=2", () => {
    const lb = ljungBox(c.x, 24, 2);
    // statsmodels reports lags 1..24 (NaN p-value where df <= 0); we skip those lags.
    for (const r of lb) {
      expect(r.statistic).toBeCloseTo(c.lb.stat[r.lag - 1]!, 8);
      expect(r.pValue).toBeCloseTo(c.lb.p[r.lag - 1] as number, 6);
    }
  });
});
